// Check all posts in one batch BEFORE modifying Google Sheets.
// A Slack failure therefore leaves the previous statuses available for retry.
const input = $input.all().map(item => item.json);
const rows = input.slice().sort((a, b) =>
  Number(a.row_number ?? 0) - Number(b.row_number ?? 0)
);
const postIds = new Set();
const contentKeys = new Set();
const now = new Date().toISOString();
const updated = [];
const newIssues = [];

for (const row of rows) {
  const postId = String(row.post_id ?? '').trim();
  const rowNumber = row.row_number ?? '?';
  // Updating by post_id is unsafe if any ID is blank or duplicated.
  if (!postId) {
    throw new Error(`Missing post_id in sheet row ${rowNumber}. Add a unique ID, then rerun.`);
  }
  if (postIds.has(postId)) {
    throw new Error(`Duplicate post_id '${postId}' in the sheet. Each post_id must be unique.`);
  }
  postIds.add(postId);

  const platform = String(row.platform ?? '').trim().toLowerCase();
  const content = String(row.content ?? '').trim();
  const imageUrl = String(row.image_url ?? '').trim();
  const problems = [];

  if (!['instagram', 'facebook', 'x'].includes(platform)) {
    problems.push('Unsupported platform');
  }
  if (!content) problems.push('Content is empty');
  // Syntax only. This does not test whether an image exists or is accessible.
  if (imageUrl && !/^https:\/\/[a-z0-9.-]+\.[a-z]{2,}(?::\d+)?(?:[/?#][^\s]*)?$/i.test(imageUrl)) {
    problems.push('Invalid image URL format');
  }

  // Duplicate text is checked within this run, for each platform separately.
  const key = platform + ':' + content.replace(/\s+/g, ' ').toLowerCase();
  if (content) {
    if (contentKeys.has(key)) problems.push('Duplicate content for the same platform');
    contentKeys.add(key);
  }

  const status = problems.length ? 'NEEDS_FIX' : 'READY_FOR_REVIEW';
  const validationResult = problems.length ? problems.join('; ') : 'OK';
  const previousStatus = String(row.status ?? '').trim();
  const previousResult = String(row.validation_result ?? '').trim();

  if (status === 'NEEDS_FIX' &&
      (previousStatus !== status || previousResult !== validationResult)) {
    newIssues.push(`Post ${postId} (row ${rowNumber}): ${validationResult}`);
  }

  updated.push({
    post_id: row.post_id,
    status,
    validation_result: validationResult,
    checked_at: now
  });
}

const message = newIssues.length
  ? `:warning: *SNS Content Quality Gate*\n${newIssues.length} new or changed issue(s):\n\n` +
    newIssues.map((line, i) => `${i + 1}. ${line}`).join('\n')
  : '';

return [{ json: {
  rows: updated,
  new_issue_count: newIssues.length,
  message
}}];

// Reach here either after a successful Slack notification, or after
// skipping Slack when there are no new issues.
const rows = $('Validate Posts Batch').first().json.rows;
if (!Array.isArray(rows)) throw new Error('Validation result is missing rows.');
return rows.map(row => ({ json: row }));
